    'not found' => 'nicht gefunden',
    '⚠️ No DNS-SD instance found — the network search needs it (core instances).' => '⚠️ Keine DNS-SD-Instanz gefunden — die Netzwerksuche braucht sie (Kern-Instanzen).',
    'ℹ️ Not searched yet.' => 'ℹ️ Noch nicht gesucht.',
